import { getProducts } from '@/lib/products'
import { revalidateTag } from 'next/cache'

export default async function AdminCatalogPage() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'

    // Simulate syncing with external ERP/PIM system
    // In production, this would make actual API calls to external systems
    await new Promise(resolve => setTimeout(resolve, 50))

    // Mark the products cache as stale
    // Using 'max' profile for stale-while-revalidate semantics
    // This allows users to continue working with stale data while
    // fresh data is fetched in the background on next access
    revalidateTag('products', 'max')
  }

  return (
    <div style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ marginBottom: '1rem' }}>Product Catalog Admin</h1>

        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '0.25rem',
              cursor: 'pointer',
              fontSize: '1rem'
            }}
          >
            Sync latest catalog
          </button>
        </form>

        <p style={{ marginTop: '0.5rem', fontSize: '0.875rem', color: '#666' }}>
          Click to sync with upstream ERP/PIM. You can continue working while sync happens in the background.
        </p>
      </div>

      <div>
        <h2 style={{ marginBottom: '1rem' }}>Products ({products.length})</h2>

        <div style={{
          display: 'grid',
          gap: '1rem',
          gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))'
        }}>
          {products.map((product) => (
            <div
              key={product.id}
              style={{
                border: '1px solid #ddd',
                borderRadius: '0.5rem',
                padding: '1rem',
                backgroundColor: 'white'
              }}
            >
              <h3 style={{ marginBottom: '0.5rem' }}>{product.name}</h3>
              <p style={{ color: '#0070f3', fontWeight: 'bold' }}>
                ${product.price}
              </p>
              <p style={{ fontSize: '0.75rem', color: '#999', marginTop: '0.5rem' }}>
                ID: {product.id}
              </p>
            </div>
          ))}
        </div>
      </div>

      <div style={{
        marginTop: '2rem',
        padding: '1rem',
        backgroundColor: '#f5f5f5',
        borderRadius: '0.5rem',
        fontSize: '0.875rem'
      }}>
        <h3 style={{ marginBottom: '0.5rem' }}>How it works:</h3>
        <ul style={{ marginLeft: '1.5rem' }}>
          <li>Product data is cached with the "products" tag</li>
          <li>Sync button triggers revalidateTag with 'max' profile</li>
          <li>Data is marked stale but served immediately</li>
          <li>Fresh data loads in background on next page visit</li>
          <li>This enables eventual consistency without blocking users</li>
        </ul>
      </div>
    </div>
  )
}

